	"rfqportal/components/buyer/i18n/i18n_vi.properties":'#Appbuyer view\r\nlanguageButtonText=Ch\\u1ecdn ng\\u00f4n ng\\u1eef\r\nmodules=Ph\\u00e2n h\\u1ec7\r\ndashboard=B\\u1ea3ng \\u0111i\\u1ec1u khi\\u1ec3n\r\ncreateRFQ=T\\u1ea1o y\\u00eau c\\u1ea7u b\\u00e1o gi\\u00e1\r\nmyRFQs=Y\\u00eau c\\u1ea7u b\\u00e1o gi\\u00e1 c\\u1ee7a t\\u00f4i\r\nquotations=B\\u00e1o gi\\u00e1\r\npurchaseOrders=\\u0110\\u01a1n \\u0111\\u1eb7t h\\u00e0ng\r\nvendorManagement=Qu\\u1ea3n l\\u00fd nh\\u00e0 cung c\\u1ea5p\r\ncontracts=H\\u1ee3p \\u0111\\u1ed3ng\r\nreports=B\\u00e1o c\\u00e1o\r\n\r\ngeneral=Chung\r\nprofile=H\\u1ed3 s\\u01a1\r\npreferences=T\\u00f9y ch\\u1ecdn\r\n\r\n\r\n# CreateRFQ view\r\ncreateRFQPageTitle=T\\u1ea1o Y\\u00eau c\\u1ea7u B\\u00e1o gi\\u00e1 (RFQ)\r\n\r\nrfqTitleLabel=Ti\\u00eau \\u0111\\u1ec1 RFQ\r\nrfqTitlePlaceholder=Nh\\u1eadp ti\\u00eau \\u0111\\u1ec1 cho y\\u00eau c\\u1ea7u b\\u00e1o gi\\u00e1\r\n\r\nrfqDescriptionLabel=M\\u00f4 t\\u1ea3 RFQ\r\nrfqDescriptionPlaceholder=Nh\\u1eadp m\\u00f4 t\\u1ea3 chi ti\\u1ebft cho y\\u00eau c\\u1ea7u b\\u00e1o gi\\u00e1\r\n\r\nrfqDueDateLabel=Ng\\u00e0y \\u0111\\u00e1o h\\u1ea1n\r\nrfqDueDatePlaceholder=Ch\\u1ecdn ng\\u00e0y \\u0111\\u00e1o h\\u1ea1n\r\n\r\nrfqBusinessDomainLabel=L\\u0129nh v\\u1ef1c kinh doanh\r\nbusinessDomainFood=Th\\u1ef1c ph\\u1ea9m\r\nbusinessDomainHK=Gia d\\u1ee5ng\r\nbusinessDomainET=\\u0110i\\u1ec7n t\\u1eed\r\nbusinessDomainONS=Kh\\u00e1c\r\n\r\nrfqAttachmentLabel=T\\u1ec7p \\u0111\\u00ednh k\\u00e8m\r\nrfqAttachmentPlaceholder=Ch\\u1ecdn t\\u1ec7p \\u0111\\u00ednh k\\u00e8m\r\nsubmitButtonText=G\\u1eedi y\\u00eau c\\u1ea7u\r\n\r\n\r\n\r\n',
